function validate([heights]) {
  if (!Array.isArray(heights) || heights.length < 1 || heights.length > 100000) return 'heights needs 1 to 10^5 people.';
  if (heights.some(h => !Number.isInteger(h) || h < 1 || h > 100000)) return 'Each height is between 1 and 10^5.';
  if (new Set(heights).size !== heights.length) return 'All heights must be different.';
  return null;
}

