function canSeePersonsCount(heights) {
  // For each pair, check the tallest person between them directly.
  return heights.map((h, i) => {
    let count = 0;
    let tallestBetween = 0;
    for (let j = i + 1; j < heights.length; j++) {
      if (Math.min(h, heights[j]) > tallestBetween) count++;
      tallestBetween = Math.max(tallestBetween, heights[j]);
    }
    return count;
  });
}

