function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(1500, 2000) : int(1, 8);
  // Small inputs use 20 consecutive heights, sometimes at the top of the range.
  const lo = size === 'large' ? 1 : (rand() < 0.3 ? 99981 : 1);
  const hi = size === 'large' ? 100000 : lo + 19;
  const used = new Set();
  const values = [];
  while (values.length < n) {
    const v = int(lo, hi);
    if (!used.has(v)) { used.add(v); values.push(v); }
  }
  const shape = int(0, 4);
  if (shape === 1) values.sort((a, b) => a - b);
  else if (shape === 2) values.sort((a, b) => b - a);
  else if (shape === 3) {
    // Zigzag: alternate tall and short people.
    values.sort((a, b) => a - b);
    const half = Math.ceil(n / 2);
    const low = values.slice(0, half), high = values.slice(half).reverse();
    values.length = 0;
    for (let i = 0; i < half; i++) { if (i < high.length) values.push(high[i]); values.push(low[i]); }
  }
  return [values];
}
